import{_ as l,o as t,a as e,a3 as i}from"./chunks/framework.CkbYhqXo.js";const p=JSON.parse('{"title":"Stuzhik Connect","description":"Stuzhik Connect — прямая P2P-передача модпаков и сборок между друзьями без серверов. Список друзей, коды подключения, VPN, безопасность.","frontmatter":{"description":"Stuzhik Connect — прямая P2P-передача модпаков и сборок между друзьями без серверов. Список друзей, коды подключения, VPN, безопасность.","head":[["meta",{"name":"keywords","content":"stuzhik connect, стужик коннект, передача модпака другу, p2p minecraft, обмен сборками minecraft, minecraft без сервера"}]]},"headers":[],"relativePath":"guide/connect.md","filePath":"guide/connect.md"}'),o={name:"guide/connect.md"};function r(n,a,h,d,c,s){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="stuzhik-connect" tabindex="-1">Stuzhik Connect <a class="header-anchor" href="#stuzhik-connect" aria-label="Permalink to &quot;Stuzhik Connect&quot;">​</a></h1><p>Прямая передача сборок и модпаков между устройствами — без промежуточных серверов, без загрузки в облако. Файлы идут напрямую от тебя к другу.</p><div class="warning custom-block"><p class="custom-block-title">Важно: работает в пределах одной сети</p><p>Stuzhik сам находит устройства <strong>в одной сети</strong> — обычной домашней/локальной или виртуальной, поднятой VPN-приложением. Собственного сервера для соединения через интернет у Stuzhik нет: если вы с другом в разных сетях (разные квартиры, города, провайдеры), напрямую вас почти всегда не пропустят домашние роутеры.</p><p>Если вы в одной сети (один Wi-Fi/локалка) — просто работает. Если в разных — нужен общий VPN, см. <a href="#если-вы-в-разных-сетях">ниже</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Нужна версия 0.0.19 или новее — у обоих</p><p>С версии 0.0.19 Connect работает по новому протоколу (Connect 2). Лаунчеры 0.0.18 и старше с ним не соединяются вовсе — обновиться нужно обоим. Если рядом есть Stuzhik другой версии, панель состояния связи в разделе «Друзья» так и скажет.</p></div><h2 id="включение" tabindex="-1">Включение <a class="header-anchor" href="#включение" aria-label="Permalink to &quot;Включение&quot;">​</a></h2><ol><li>Открой «Друзья» в боковой панели</li><li>Нажми «Включить»</li><li>При первом включении лаунчер спросит, кто тебя видит. По умолчанию — никто: Connect включён, но для сети тебя нет, пока не выберешь «Только друзья» или «Все в сети» (подробнее — в разделе <a href="#видимость">Видимость</a>)</li><li>Твой код — <code>STUZHIK-XXXXXX</code>, 6 символов после префикса. Кнопка «Пригласить» копирует его</li></ol><h2 id="подключение-к-другу" tabindex="-1">Подключение к другу <a class="header-anchor" href="#подключение-к-другу" aria-label="Permalink to &quot;Подключение к другу&quot;">​</a></h2><h3 id="автопоиск" tabindex="-1">Автопоиск <a class="header-anchor" href="#автопоиск" aria-label="Permalink to &quot;Автопоиск&quot;">​</a></h3><p>Если вы в одной сети, Stuzhik находит устройства друг друга сам — вводить ничего не нужно, устройство появится в списке «Люди». Друг при этом не должен быть «Невидим».</p><h3 id="по-коду" tabindex="-1">По коду <a class="header-anchor" href="#по-коду" aria-label="Permalink to &quot;По коду&quot;">​</a></h3><ol><li>Попроси у друга его код</li><li>Нажми «Добавить устройство» и вставь код</li><li>Подтверди кнопкой «Добавить устройство»</li></ol><p>Код ищет друга той же рассылкой по сети, что и автопоиск, — он нужен, чтобы попасть точно к нужному человеку, когда устройств в списке много. Поэтому и работает код только в одной сети (реальной или VPN) и только если друг не «Невидим».</p><p>Код старого формата (4 символа) больше не принимается. Попроси у друга новый — у него код обновится сам после обновления лаунчера.</p><h3 id="по-адресу" tabindex="-1">По адресу <a class="header-anchor" href="#по-адресу" aria-label="Permalink to &quot;По адресу&quot;">​</a></h3><p>Если устройство не находится само — например, вы в Tailscale, — нажми «Добавить устройство» и введи адрес друга: <code>100.64.0.5</code> или <code>100.64.0.5:19848</code>. Порт можно не писать, подставится стандартный 19848. Указывать его нужно, только если у друга Connect занял резервный порт.</p><h2 id="друзья" tabindex="-1">Друзья <a class="header-anchor" href="#друзья" aria-label="Permalink to &quot;Друзья&quot;">​</a></h2><p>Найденное устройство — ещё не друг. Чтобы добавить:</p><ol><li>Нажми «⋯» у человека (или правой кнопкой по нему) → «Добавить в друзья». После добавления по коду или адресу лаунчер предложит это сам</li><li>Друг принимает заявку у себя — она приходит во «Входящие» (колокол) и в список «Люди»</li><li>После этого вы друзья: лаунчер узнаёт друга по подписи его ключом, и выдать себя за него нельзя</li></ol><p>Друзей лаунчер помнит вместе с адресами. При включении Connect он сам стучится к ним по последнему адресу — поэтому друг находится и там, где автопоиск не работает (см. <a href="#tailscale-и-другие-сети-без-широковещания">Tailscale</a>).</p><h3 id="проверить-связь" tabindex="-1">Проверить связь <a class="header-anchor" href="#проверить-связь" aria-label="Permalink to &quot;Проверить связь&quot;">​</a></h3><p>В карточке человека (нажми на него в списке) есть кнопка «Проверить связь». Она делает настоящее рукопожатие — то же, что перед передачей сборки, — сразу по каждому известному адресу и показывает итог для каждого: «отвечает, N мс», «не отвечает», «другая версия Stuzhik» или «вы скрыты от него». Рядом с адресом — что это за сеть: локальная, Tailscale, Radmin VPN, Hamachi или интернет.</p><p>Другу проверка доступна, даже когда он «не в сети»: если запомненный адрес ожил, друг сразу появится в списке.</p><h2 id="видимость" tabindex="-1">Видимость <a class="header-anchor" href="#видимость" aria-label="Permalink to &quot;Видимость&quot;">​</a></h2><p>Режим выбирается в настройках Connect:</p><table tabindex="0"><thead><tr><th>Режим</th><th>Кто тебя видит</th></tr></thead><tbody><tr><td>Невидим</td><td>Никто. Устройство не выходит в сеть вовсе: не отвечает никому и само ничего о себе не объявляет. Друзья тебя не найдут — только ты их</td></tr><tr><td>Только друзья</td><td>Ник, сборки и во что ты играешь видят только друзья. Само присутствие устройства в сети заметно всем — иначе друзья не смогли бы тебя найти, — но узнать в нём именно тебя может только друг: опознавательная метка меняется каждые 10 минут и посторонним ничего не говорит</td></tr><tr><td>Все в сети</td><td>Любой пользователь Stuzhik в этой сети видит тебя в списке — с ником, если его показ включён</td></tr></tbody></table><p>Скрыться можно и от одного друга: «Скрыться от этого друга» в его меню. Для него ты «Невидим», остальные видят тебя как обычно.</p><h2 id="профиль" tabindex="-1">Профиль <a class="header-anchor" href="#профиль" aria-label="Permalink to &quot;Профиль&quot;">​</a></h2><p>Своя карточка — «Мой профиль» → «Настроить», вкладка «Оформление». Карточку другие видят ровно такой, какой ты её видишь у себя:</p><ul><li><strong>Баннер</strong> — живой эффект в шапке или на всю карточку и «Цвет баннера»</li><li><strong>Аватар</strong> — картинка обрезается до квадрата 256×256. «Фон под картинкой»: «Как обычно», свой цвет или «Прозрачный» — для PNG и WebP с прозрачным фоном</li><li><strong>Рамки</strong> — отдельно для аватара и для всей карточки: линия, двойная, свечение, градиент и анимированные. «Цвет рамок» — как акцент или свой</li><li><strong>Акцент</strong> и строка «О себе»</li></ul><p>Цвет можно выбрать на квадрате, пипеткой с экрана или вставить строкой: <code>#4f8cff</code>, <code>rgb(79 140 255)</code>, <code>hsl(…)</code> или просто название цвета.</p><p>Кто видит оформление, решает «Оформление профиля видят» в настройках Connect: «Все, кому я виден» или «Только друзья». Ник и видимость в сети настраиваются отдельно.</p><h2 id="передача-сборок" tabindex="-1">Передача сборок <a class="header-anchor" href="#передача-сборок" aria-label="Permalink to &quot;Передача сборок&quot;">​</a></h2><p>Отправить сборку другу нельзя: Connect работает только «на забор». Друг сам берёт сборку, а у тебя лаунчер спрашивает разрешения — и в вопросе прямо написано, что друг хочет получить от тебя.</p><h3 id="открыть-сборку-друзьям" tabindex="-1">Открыть сборку друзьям <a class="header-anchor" href="#открыть-сборку-друзьям" aria-label="Permalink to &quot;Открыть сборку друзьям&quot;">​</a></h3><p>По умолчанию сборки не опубликованы — для сети их нет. Открыть: правый клик по сборке (или «⋯») → «Публикация» → «Друзьям» или «Всем в сети». Чтобы друзьям было из чего выбрать, в настройках Connect должно быть включено «Показывать список модпаков».</p><p>Кто может просить сборку и спрашивать ли тебя каждый раз — тоже в настройках Connect. По умолчанию просить могут только друзья, и каждая передача — только с твоего согласия.</p><h3 id="забрать-сборку-у-друга" tabindex="-1">Забрать сборку у друга <a class="header-anchor" href="#забрать-сборку-у-друга" aria-label="Permalink to &quot;Забрать сборку у друга&quot;">​</a></h3><ol><li>Открой карточку друга → «Сборки» → «Обновить», чтобы получить список</li><li>Нажми «Взять» у нужной сборки. Или в меню друга «Взять сборку…» — там сначала видно, что скачается, а что у тебя уже есть</li><li>У друга появится вопрос «Запрос на передачу: … хочет получить от вас …» — файлы поедут, только когда он нажмёт «Разрешить»</li></ol><p>Вопрос не пропадает по таймеру: он ждёт ответа, пока просящий на связи. Одно «Разрешить» действует на всю передачу — если связь оборвётся, докачка не спросит заново. Галочка «Запомнить для этого пользователя» запоминает ответ для этого друга и этой сборки.</p><h3 id="во-время-передачи" tabindex="-1">Во время передачи <a class="header-anchor" href="#во-время-передачи" aria-label="Permalink to &quot;Во время передачи&quot;">​</a></h3><ul><li>Прогресс — в блоке передач раздела «Друзья», полный список — «Все передачи»</li><li>Пауза, продолжение и отмена — там же</li><li>Передаются только недостающие и изменившиеся файлы</li><li>Оборвалась связь — передача продолжится с того места, где остановилась, а не сначала</li><li>Каждый скачанный файл проверяется по хешу, прежде чем лечь в сборку</li></ul><h2 id="coop-build" tabindex="-1">Совместная сборка <a class="header-anchor" href="#coop-build" aria-label="Permalink to &quot;Совместная сборка {#coop-build}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Экспериментальная функция</p><p>Включается в Настройки → Общие → «Экспериментальные функции». Пока выключена, её нет нигде в интерфейсе.</p></div><p>Сборку можно собирать вместе с друзьями: хозяин открывает комнату, друзья заходят, предлагают и обсуждают моды, правят конфиги.</p><h3 id="открыть-комнату" tabindex="-1">Открыть комнату <a class="header-anchor" href="#открыть-комнату" aria-label="Permalink to &quot;Открыть комнату&quot;">​</a></h3><p>«Друзья» → «Собрать вместе» → своя сборка, «Новая сборка» (с нуля — друзья добавят моды сами) или проект из <a href="/guide/builder.html">Конструктора</a>. Там же — «Кто сможет войти»:</p><ul><li><strong>«Друзья»</strong> — по умолчанию, только подтверждённые друзья</li><li><strong>«Все, кто меня видит»</strong> — незнакомцы только смотрят</li><li><strong>«По приглашению»</strong> — только отмеченные в настройках комнаты</li></ul><h3 id="в-комнате" tabindex="-1">В комнате <a class="header-anchor" href="#в-комнате" aria-label="Permalink to &quot;В комнате&quot;">​</a></h3><ul><li><strong>Роли.</strong> «Редактор» меняет состав сам, «Участник» выносит изменения на голосование, «Зритель» смотрит и обсуждает. Незнакомец всегда зритель. Роли и права (смотреть и править конфиги, голосовать, забирать сборку без вопроса, копировать комнату) хозяин настраивает в настройках комнаты</li><li><strong>Редактор сборки</strong> — «Открыть редактор сборки»: вкладки «Состав», «Каталог», «Совместимость», «Конфиги». Ставит моды только хозяин: правка участника — это предложение, а сами файлы его лаунчер берёт с Modrinth и CurseForge</li><li><strong>Совместимость</strong> — «По составу» и «Граф зависимостей» доступны всем в комнате, ставить сборку для этого не нужно</li><li><strong>Предложения и обсуждение</strong> — голосования, лента «Правки сборки» (изменение состава можно отменить) и «Обсуждение» — общий чат комнаты</li></ul><h3 id="своя-копия" tabindex="-1">Своя копия <a class="header-anchor" href="#своя-копия" aria-label="Permalink to &quot;Своя копия&quot;">​</a></h3><p>«Забрать сборку» ставит себе копию сборки хозяина; «Обновлять мою копию автоматически» догоняет его изменения. Сделать свою комнату на основе чужой («Своя комната на основе этой») можно, только если хозяин дал право «Копировать комнату» — по умолчанию его нет ни у кого.</p><p>Хозяин ушёл из сети — комната закрывается. Закреплённая комната («Закрепить комнату») вернётся сама, когда хозяин снова появится.</p><h2 id="если-вы-в-разных-сетях" tabindex="-1">Если вы в разных сетях <a class="header-anchor" href="#если-вы-в-разных-сетях" aria-label="Permalink to &quot;Если вы в разных сетях&quot;">​</a></h2><p>Домашние роутеры и мобильный интернет почти всегда блокируют прямое соединение между разными сетями — так работает NAT, это не баг Stuzhik и не то, что мы можем обойти сами. Рабочий вариант — общая виртуальная сеть поверх интернета: вы оба ставите одно и то же VPN-приложение, оно объединяет ваши устройства в одну сеть, и дальше Connect работает в ней.</p><p>Мы не разрабатываем и не поддерживаем эти приложения — просто рекомендация того, что работает. Stuzhik не связан с этими сервисами и не распространяет их: здесь только названия, официальный сайт найди через поисковик.</p><table tabindex="0"><thead><tr><th>Вариант</th><th>Сложность</th><th>Как находятся друзья</th></tr></thead><tbody><tr><td>Radmin VPN</td><td>Лёгкая</td><td>Сами, как в обычной локалке</td></tr><tr><td>ZeroTier</td><td>Средняя</td><td>Сами, когда вы оба в одной сети ZeroTier</td></tr><tr><td>Tailscale</td><td>Сложная</td><td>Один раз по адресу, дальше сами — <a href="#tailscale-и-другие-сети-без-широковещания">см. ниже</a></td></tr></tbody></table><p>Hamachi тоже собирает устройства в общую сеть, и поиск в нём работает сам. Подсказки по этим вариантам есть и в самом лаунчере, в разделе «Друзья» (тоже без ссылок — только названия).</p><h3 id="tailscale-и-другие-сети-без-широковещания" tabindex="-1">Tailscale и другие сети без широковещания <a class="header-anchor" href="#tailscale-и-другие-сети-без-широковещания" aria-label="Permalink to &quot;Tailscale и другие сети без широковещания&quot;">​</a></h3><p>Tailscale и другие туннели уровня IP не передают широковещательные пакеты, поэтому автопоиск и код в них никого не находят. Друга нужно добавить по адресу — но только один раз:</p><ol><li>Узнай у друга его адрес в Tailscale — вида <code>100.x.y.z</code></li><li>«Добавить устройство» → введи этот адрес. Порт можно не писать: по умолчанию 19848</li><li>Добавь его в друзья — друг принимает заявку</li></ol><p>Дальше всё само. Как только вы друзья, после первого же рукопожатия, в котором друг подтвердил себя подписью, лаунчер запоминает его адрес. При включении Connect и потом раз в 5 минут он сам стучится по запомненному адресу, а дозвонившись — держит друга в сети, пока тот отвечает. Друг, который достучался до тебя сам, тоже появляется в списке. Комнаты совместных сборок, оформление профиля и «играет в …» доходят до такого друга так же, как по локальной сети.</p><p>Запоминаются только подтверждённые друзья. В режиме «Невидим» лаунчер не стучится никому, а к другу, от которого ты скрыт, — никогда.</p><h2 id="брандмауэр" tabindex="-1">Брандмауэр <a class="header-anchor" href="#брандмауэр" aria-label="Permalink to &quot;Брандмауэр&quot;">​</a></h2><p>Connect работает только по UDP: поиск — на порту 19847, соединения — на 19848. Если порт занят другой программой, Connect берёт резервный (+10, +20 или +30).</p><p>На Windows для обоих портов нужно одно правило брандмауэра — «Stuzhik Connect». Его добавляет кнопка «Добавить правило брандмауэра» в разделе «Друзья» (Windows попросит разрешения). Правило из прежних версий открывало передачу по TCP и теперь не помогает, а экран связи этого пока не замечает (<a href="/known-issues.html">известная проблема</a>). Если правило добавляли до 0.0.19, нажми «Добавить правило брандмауэра» ещё раз — новое заменит старое.</p><h2 id="безопасность" tabindex="-1">Безопасность <a class="header-anchor" href="#безопасность" aria-label="Permalink to &quot;Безопасность&quot;">​</a></h2><ul><li>Соединения Connect идут по QUIC с TLS 1.3 и шифруются целиком — и файлы, и каждое сообщение, включая само рукопожатие. Обмен ключами — гибрид X25519 и ML-KEM-768, ключи новые для каждого соединения</li><li>Друга лаунчер узнаёт по подписи его ключом, привязанной к этому соединению: подслушанную подпись в другом соединении не предъявить</li><li>Наблюдатель в той же сети видит факт соединения, его объём и то, что это Stuzhik, — но не содержимое</li><li>Файлы уходят только после твоего «Разрешить» — без спроса у тебя ничего не заберут. Так по умолчанию; в настройках выдачи «Спрашивать разрешение» можно переключить на «Кроме друзей» или «Никогда»</li><li>Исполняемые файлы (<code>.exe</code>, <code>.bat</code>, <code>.ps1</code>, <code>.sh</code> и т.п.) не передаются никогда — даже с суффиксом <code>.disabled</code></li><li>Заблокированный не может отправлять запросы и не виден в списке</li></ul><h2 id="решение-проблем" tabindex="-1">Решение проблем <a class="header-anchor" href="#решение-проблем" aria-label="Permalink to &quot;Решение проблем&quot;">​</a></h2><h3 id="друг-не-находится-в-сети" tabindex="-1">Друг не находится в сети <a class="header-anchor" href="#друг-не-находится-в-сети" aria-label="Permalink to &quot;Друг не находится в сети&quot;">​</a></h3><ol><li>Оба включили Connect, и у обоих версия 0.0.19 или новее?</li><li>Друг не «Невидим»? В этом режиме его не найти никак</li><li>Вы точно в одной сети — физической или через общий VPN? VPN-приложение должно быть подключено у обоих, а не просто установлено</li><li>В Tailscale автопоиск не работает — добавь друга по адресу (<a href="#tailscale-и-другие-сети-без-широковещания">см. выше</a>)</li><li>Брандмауэр: в разделе «Друзья» — «Добавить правило брандмауэра»</li><li>Если вы уже друзья — «Проверить связь» в его карточке покажет, что именно не так</li></ol><h3 id="передача-зависла" tabindex="-1">Передача зависла <a class="header-anchor" href="#передача-зависла" aria-label="Permalink to &quot;Передача зависла&quot;">​</a></h3><ol><li>Проверь передачи в разделе «Друзья» — она может стоять на паузе</li><li>Продолжи вручную</li><li>Не помогает — отмени и возьми сборку заново: передаются только недостающие и изменившиеся файлы</li></ol><h3 id="не-приходит-запрос-в-друзья" tabindex="-1">Не приходит запрос в друзья <a class="header-anchor" href="#не-приходит-запрос-в-друзья" aria-label="Permalink to &quot;Не приходит запрос в друзья&quot;">​</a></h3><ul><li>У друга в настройках Connect может быть выключено «Принимать заявки в друзья» — тогда заявки отбрасываются молча, и отправитель об этом не узнаёт</li><li>Если друг «Невидим», его не видно — и заявку отправить некуда</li><li>В режиме «Только друзья» незнакомцы видят тебя без ника, как «Аноним». Чтобы друг точно нашёл именно тебя, дай ему свой код</li></ul><h2 id="что-дальше" tabindex="-1">Что дальше? <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше?&quot;">​</a></h2><ul><li><a href="/guide/modpacks.html">Модпаки</a></li><li><a href="/guide/collections.html">Сборки модов</a></li><li><a href="/faq.html">FAQ</a></li></ul>',76)])])}const b=l(o,[["render",r]]);export{p as __pageData,b as default};
